//! Channel direction semantics — send-only, receive-only, assignment, params, select compile.

go_run_cases! {
    send_only_chan_typed_var => ("package main; import \"fmt\"; func main() { ch := make(chan int, 1); var out chan<- int = ch; out <- 7; fmt.Println(<-ch) }", vec!["7"]),
    send_only_buffered_send => ("package main; import \"fmt\"; func main() { ch := make(chan int, 1); var out chan<- int = ch; out <- 3; fmt.Println(<-ch) }", vec!["3"]),
    receive_only_chan_typed_var => ("package main; import \"fmt\"; func main() { ch := make(chan int, 1); ch <- 5; var in <-chan int = ch; fmt.Println(<-in) }", vec!["5"]),
    bidirectional_from_make => ("package main; import \"fmt\"; func main() { ch := make(chan string, 1); ch <- \"hi\"; fmt.Println(<-ch) }", vec!["hi"]),
    assign_bidir_to_send_only => ("package main; import \"fmt\"; func main() { ch := make(chan int, 2); var s chan<- int = ch; s <- 1; s <- 2; fmt.Println(<-ch); fmt.Println(<-ch) }", vec!["1", "2"]),
    assign_bidir_to_recv_only => ("package main; import \"fmt\"; func main() { ch := make(chan int, 1); ch <- 9; var r <-chan int = ch; fmt.Println(<-r) }", vec!["9"]),
    send_only_param_accepts_bidir => ("package main; import \"fmt\"; func send(ch chan<- int, v int) { ch <- v }; func main() { ch := make(chan int, 1); send(ch, 4); fmt.Println(<-ch) }", vec!["4"]),
    recv_only_param_accepts_bidir => ("package main; import \"fmt\"; func recv(ch <-chan int) int { return <-ch }; func main() { ch := make(chan int, 1); ch <- 6; fmt.Println(recv(ch)) }", vec!["6"]),
    convert_bidir_to_send_only => ("package main; import \"fmt\"; func main() { ch := make(chan int, 1); out := (chan<- int)(ch); out <- 8; fmt.Println(<-ch) }", vec!["8"]),
    convert_bidir_to_recv_only => ("package main; import \"fmt\"; func main() { ch := make(chan int, 1); ch <- 2; in := (<-chan int)(ch); fmt.Println(<-in) }", vec!["2"]),
    send_only_string_channel => ("package main; import \"fmt\"; func main() { ch := make(chan string, 1); var s chan<- string = ch; s <- \"go\"; fmt.Println(<-ch) }", vec!["go"]),
    recv_only_string_channel => ("package main; import \"fmt\"; func main() { ch := make(chan string, 1); ch <- \"vybe\"; var r <-chan string = ch; fmt.Println(<-r) }", vec!["vybe"]),
    send_only_bool_channel => ("package main; import \"fmt\"; func main() { ch := make(chan bool, 1); var s chan<- bool = ch; s <- true; fmt.Println(<-ch) }", vec!["true"]),
    recv_only_struct_channel => ("package main; import \"fmt\"; type item struct { n int }; func main() { ch := make(chan item, 1); ch <- item{n: 3}; var r <-chan item = ch; fmt.Println((<-r).n) }", vec!["3"]),
    send_only_from_function_return => ("package main; import \"fmt\"; func mk() (chan<- int, chan int) { ch := make(chan int, 1); return ch, ch }; func main() { out, rd := mk(); out <- 11; fmt.Println(<-rd) }", vec!["11"]),
    recv_only_from_function_param => ("package main; import \"fmt\"; func read(ch <-chan int) { fmt.Println(<-ch) }; func main() { ch := make(chan int, 1); ch <- 12; read(ch) }", vec!["12"]),
    bidirectional_reassign_send_only => ("package main; import \"fmt\"; func main() { ch := make(chan int, 1); var s chan<- int = ch; s <- 1; var b chan int = ch; fmt.Println(<-b) }", vec!["1"]),
    bidirectional_reassign_recv_only => ("package main; import \"fmt\"; func main() { ch := make(chan int, 1); ch <- 2; var r <-chan int = ch; var b chan int = ch; fmt.Println(<-b) }", vec!["2"]),
    send_only_multiple_values => ("package main; import \"fmt\"; func main() { ch := make(chan int, 3); var s chan<- int = ch; s <- 1; s <- 2; s <- 3; fmt.Println(<-ch + <-ch + <-ch) }", vec!["6"]),
    recv_only_range_not_applicable_use_two => ("package main; import \"fmt\"; func main() { ch := make(chan int, 2); ch <- 1; ch <- 2; var r <-chan int = ch; fmt.Println(<-r); fmt.Println(<-r) }", vec!["1", "2"]),
    send_only_in_struct_field => ("package main; import \"fmt\"; type sink struct { ch chan<- int }; func main() { ch := make(chan int, 1); s := sink{ch: ch}; s.ch <- 5; fmt.Println(<-ch) }", vec!["5"]),
    recv_only_in_struct_field => ("package main; import \"fmt\"; type source struct { ch <-chan int }; func main() { ch := make(chan int, 1); ch <- 6; s := source{ch: ch}; fmt.Println(<-s.ch) }", vec!["6"]),
    send_only_interface_box => ("package main; import \"fmt\"; func main() { ch := make(chan int, 1); var s chan<- int = ch; var v interface{} = s; _ = v; s <- 7; fmt.Println(<-ch) }", vec!["7"]),
    send_only_after_close_read_side => ("package main; import \"fmt\"; func main() { ch := make(chan int, 1); ch <- 1; close(ch); var r <-chan int = ch; v, ok := <-r; fmt.Println(v); fmt.Println(ok) }", vec!["1", "true"]),
    send_only_unbuffered_buffered_fallback => ("package main; import \"fmt\"; func main() { ch := make(chan int, 1); var s chan<- int = ch; s <- 9; fmt.Println(<-ch) }", vec!["9"]),
    recv_only_zero_value_from_closed => ("package main; import \"fmt\"; func main() { ch := make(chan int); close(ch); var r <-chan int = ch; v, ok := <-r; fmt.Println(v); fmt.Println(ok) }", vec!["0", "false"]),
    send_only_chan_of_chan => ("package main; import \"fmt\"; func main() { inner := make(chan int, 1); outer := make(chan chan int, 1); var s chan<- chan int = outer; s <- inner; got := <-outer; got <- 4; fmt.Println(<-inner) }", vec!["4"]),
    recv_only_chan_of_chan => ("package main; import \"fmt\"; func main() { inner := make(chan int, 1); inner <- 5; outer := make(chan chan int, 1); outer <- inner; var r <-chan chan int = outer; ch := <-r; fmt.Println(<-ch) }", vec!["5"]),
    send_only_nil_map_not_chan => ("package main; import \"fmt\"; func main() { ch := make(chan int, 1); var s chan<- int = ch; if s != nil { s <- 1 }; fmt.Println(<-ch) }", vec!["1"]),
    direction_on_nil_chan_send => ("package main; import \"fmt\"; func main() { var s chan<- int; fmt.Println(s == nil) }", vec!["true"]),
    direction_on_nil_chan_recv => ("package main; import \"fmt\"; func main() { var r <-chan int; fmt.Println(r == nil) }", vec!["true"]),
    send_only_after_recv_drains => ("package main; import \"fmt\"; func main() { ch := make(chan int, 1); var s chan<- int = ch; var r <-chan int = ch; s <- 10; fmt.Println(<-r) }", vec!["10"]),
    func_returns_recv_only_from_local => ("package main; import \"fmt\"; func source() <-chan int { ch := make(chan int, 1); ch <- 13; return ch }; func main() { fmt.Println(<-source()) }", vec!["13"]),
    func_accepts_send_only_and_bidir => ("package main; import \"fmt\"; func fill(ch chan<- int) { ch <- 14 }; func main() { ch := make(chan int, 1); fill(ch); fmt.Println(<-ch) }", vec!["14"]),
    send_only_with_select_default_nonblock => ("package main; import \"fmt\"; func main() { ch := make(chan int, 1); var s chan<- int = ch; select { case s <- 1: fmt.Println(\"sent\"); default: fmt.Println(\"def\") } }", vec!["sent"]),
    recv_only_with_select_ready => ("package main; import \"fmt\"; func main() { ch := make(chan int, 1); ch <- 15; var r <-chan int = ch; select { case v := <-r: fmt.Println(v); default: fmt.Println(0) } }", vec!["15"]),
    send_only_capacity_via_underlying => ("package main; import \"fmt\"; func main() { ch := make(chan int, 2); var s chan<- int = ch; fmt.Println(cap(s)) }", vec!["2"]),
    recv_only_len_via_underlying => ("package main; import \"fmt\"; func main() { ch := make(chan int, 2); ch <- 1; var r <-chan int = ch; fmt.Println(len(r)) }", vec!["1"]),
    send_only_pointer_element_type => ("package main; import \"fmt\"; func main() { ch := make(chan *int, 1); n := 16; var s chan<- *int = ch; s <- &n; fmt.Println(<-*(<-ch)) }", vec!["16"]),
    recv_only_slice_element_type => ("package main; import \"fmt\"; func main() { ch := make(chan []int, 1); ch <- []int{1, 2}; var r <-chan []int = ch; fmt.Println(len(<-r)) }", vec!["2"]),
    send_only_in_map_value => ("package main; import \"fmt\"; func main() { ch := make(chan int, 1); m := map[string]chan<- int{\"k\": ch}; m[\"k\"] <- 17; fmt.Println(<-ch) }", vec!["17"]),
    recv_only_in_slice => ("package main; import \"fmt\"; func main() { ch := make(chan int, 1); ch <- 18; arr := []<-chan int{ch}; fmt.Println(<-arr[0]) }", vec!["18"]),
    send_only_passed_to_helper => ("package main; import \"fmt\"; func push(ch chan<- int, v int) { ch <- v }; func main() { ch := make(chan int, 1); push(ch, 19); fmt.Println(<-ch) }", vec!["19"]),
    recv_only_passed_to_helper => ("package main; import \"fmt\"; func pull(ch <-chan int) int { return <-ch }; func main() { ch := make(chan int, 1); ch <- 20; fmt.Println(pull(ch)) }", vec!["20"]),
    bidirectional_close_then_recv_only => ("package main; import \"fmt\"; func main() { ch := make(chan int, 1); ch <- 21; close(ch); var r <-chan int = ch; fmt.Println(<-r) }", vec!["21"]),
    send_only_after_bidir_close_fails_compile_side => ("package main; import \"fmt\"; func main() { ch := make(chan int, 1); close(ch); var s chan<- int = ch; _, ok := (<-chan int)(ch); fmt.Println(ok) }", vec!["false"]),
    direction_preserved_in_type_alias => ("package main; import \"fmt\"; type sendInt chan<- int; func main() { ch := make(chan int, 1); var s sendInt = ch; s <- 22; fmt.Println(<-ch) }", vec!["22"]),
    recv_only_in_interface_switch => ("package main; import \"fmt\"; func tag(v interface{}) { switch v.(type) { case <-chan int: fmt.Println(\"recv\"); case chan<- int: fmt.Println(\"send\"); default: fmt.Println(\"other\") } }; func main() { ch := make(chan int); tag((<-chan int)(ch)) }", vec!["recv"]),
    send_only_in_interface_switch => ("package main; import \"fmt\"; func tag(v interface{}) { switch v.(type) { case chan<- int: fmt.Println(\"send\"); default: fmt.Println(\"other\") } }; func main() { ch := make(chan int); tag((chan<- int)(ch)) }", vec!["send"]),
    send_only_with_comma_ok_receive_on_bidir => ("package main; import \"fmt\"; func main() { ch := make(chan int, 1); ch <- 23; v, ok := <-ch; fmt.Println(v); fmt.Println(ok) }", vec!["23", "true"]),
    recv_only_two_receives_fifo => ("package main; import \"fmt\"; func main() { ch := make(chan int, 2); ch <- 1; ch <- 2; var r <-chan int = ch; fmt.Println(<-r); fmt.Println(<-r) }", vec!["1", "2"]),
    send_only_pair_buffered => ("package main; import \"fmt\"; func main() { ch := make(chan int, 1); var s chan<- int = ch; s <- 24; fmt.Println(<-ch) }", vec!["24"]),
    func_literal_send_only_param => ("package main; import \"fmt\"; func main() { ch := make(chan int, 1); f := func(c chan<- int) { c <- 25 }; f(ch); fmt.Println(<-ch) }", vec!["25"]),
    func_literal_recv_only_param => ("package main; import \"fmt\"; func main() { ch := make(chan int, 1); ch <- 26; f := func(c <-chan int) { fmt.Println(<-c) }; f(ch) }", vec!["26"]),
    send_only_empty_struct_chan => ("package main; import \"fmt\"; type sig struct{}; func main() { ch := make(chan sig, 1); var s chan<- sig = ch; s <- sig{}; fmt.Println(\"ok\") }", vec!["ok"]),
    recv_only_after_multiple_sends => ("package main; import \"fmt\"; func main() { ch := make(chan int, 3); ch <- 1; ch <- 2; ch <- 3; var r <-chan int = ch; fmt.Println(<-r + <-r + <-r) }", vec!["6"]),
    send_only_from_make_with_capacity => ("package main; import \"fmt\"; func main() { ch := make(chan int, 4); var s chan<- int = ch; s <- 27; fmt.Println(len(ch)) }", vec!["1"]),
    recv_only_drains_buffered => ("package main; import \"fmt\"; func main() { ch := make(chan int, 2); ch <- 28; ch <- 29; var r <-chan int = ch; fmt.Println(<-r); fmt.Println(len(ch)) }", vec!["28", "1"]),
}

go_compile_cases! {
    cannot_close_send_only_compile => "package main; func main() { ch := make(chan int, 1); var s chan<- int = ch; close(s) }",
    cannot_close_recv_only_compile => "package main; func main() { ch := make(chan int, 1); var r <-chan int = ch; close(r) }",
    cannot_recv_from_send_only_compile => "package main; func main() { ch := make(chan int, 1); var s chan<- int = ch; _ = <-s }",
    cannot_send_to_recv_only_compile => "package main; func main() { ch := make(chan int, 1); var r <-chan int = ch; r <- 1 }",
    select_send_on_recv_only_compile => "package main; func main() { ch := make(chan int, 1); var r <-chan int = ch; select { case r <- 1: default: } }",
    select_recv_assign_send_only_compile => "package main; func main() { ch := make(chan int, 1); var s chan<- int = ch; select { case v := <-s: _ = v; default: } }",
    select_two_send_only_compile => "package main; func main() { a := make(chan int, 1); b := make(chan int, 1); var sa chan<- int = a; var sb chan<- int = b; select { case sa <- 1: case sb <- 2: } }",
    select_two_recv_only_compile => "package main; func main() { a := make(chan int, 1); b := make(chan int, 1); a <- 1; b <- 2; var ra <-chan int = a; var rb <-chan int = b; select { case <-ra: case <-rb: } }",
    assign_send_only_to_recv_only_compile => "package main; func main() { ch := make(chan int, 1); var s chan<- int = ch; var r <-chan int = s }",
    assign_recv_only_to_send_only_compile => "package main; func main() { ch := make(chan int, 1); var r <-chan int = ch; var s chan<- int = r }",
    chan_direction_mismatch_return_compile => "package main; func bad() chan int { var s chan<- int = make(chan int, 1); return s }",
    chan_direction_mismatch_param_compile => "package main; func use(ch chan int) {}; func main() { var s chan<- int = make(chan int, 1); use(s) }",
    make_with_send_only_type_compile => "package main; func main() { _ = make(chan<- int) }",
    make_with_recv_only_type_compile => "package main; func main() { _ = make(<-chan int) }",
    select_default_with_directed_both_compile => "package main; func main() { ch := make(chan int, 1); var s chan<- int = ch; var r <-chan int = ch; select { case s <- 1: case v := <-r: _ = v; default: } }",
    send_only_unbuffered_with_goroutine_compile => "package main; func main() { ch := make(chan int); var s chan<- int = ch; go func() { s <- 1 }(); _ = <-ch }",
    recv_only_unbuffered_with_goroutine_compile => "package main; func main() { ch := make(chan int); var r <-chan int = ch; go func() { ch <- 2 }(); _ = <-r }",
}
